        List<Map<String, Object>> fixed = List.of(
                liveItem(a.key("ok"), a.channel, a.liveAsset, a.liveGrant, T_1020, T_1040),
                liveItem(b.key("good"), b.channel, b.liveAsset, b.liveGrant, T_1020, T_1040));
